#!/bin/bash
set -e
echo "📡 환경분기 + 모바일배너 일괄 배포"

echo "→ ai-tactile-gen/index.html"
SHA=$(curl -s -H "Authorization: Bearer $GITHUB_TOKEN" "https://api.github.com/repos/byeol-coder/project_byeol/contents/ai-tactile-gen/index.html" | python3 -c "import json,sys; print(json.load(sys.stdin).get('sha',''))")
python3 - << 'PYEOF'
import base64,json,urllib.request,os,subprocess
b64=""
token=os.environ.get("GITHUB_TOKEN","")
sha=subprocess.check_output("echo $SHA",shell=True).decode().strip()
data=json.dumps({"message":"feat: API env-detection fallback + mobile banner","content":b64,"sha":sha}).encode()
req=urllib.request.Request("https://api.github.com/repos/byeol-coder/project_byeol/contents/ai-tactile-gen/index.html",data=data,headers={"Authorization":f"Bearer {token}","Content-Type":"application/json"},method="PUT")
try:
    print("  ✅", urllib.request.urlopen(req).status)
except urllib.error.HTTPError as e:
    print("  ❌", e.code, e.read().decode()[:120])
PYEOF
sleep 1

